// browser_scroll 实现：无 ref 滚页面，有 ref 滚该元素内部容器
#include "browser_scroll.h" // 自身声明
#include "browser_tool/tool_helpers.h" // EvalReply
#include "utils/js_builder.h" // js::Element
#include "utils/json_util.h" // 参数读取
void BrowserScrollTool::Run(const ToolRequest& req) { std::string direction = "down"; ArgGetString(req.args, "direction", direction); double amount = 0; if (!ArgGetDouble(req.args, "amount", amount) || amount <= 0) amount = 600; double dx = 0, dy = 0; if (direction == "up") dy = -amount; else if (direction == "down") dy = amount; else if (direction == "left") dx = -amount; else if (direction == "right") dx = amount; else { tool::ReplyError(req.id, "direction 需为 up/down/left/right"); return; } std::string ref; ArgGetString(req.args, "ref", ref); const std::string dx_text = std::to_string(static_cast<int>(dx)); const std::string dy_text = std::to_string(static_cast<int>(dy)); const std::string script = ref.empty() ? "(function(){window.scrollBy({left:" + dx_text + ",top:" + dy_text + "});" "return JSON.stringify({x:Math.round(window.scrollX),y:Math.round(window.scrollY)});})()" : js::Element(ref, "el.scrollBy({left:" + dx_text + ",top:" + dy_text + "});" "return JSON.stringify({x:Math.round(el.scrollLeft),y:Math.round(el.scrollTop)});"); tool::EvalReply(req, script, "position", false, "滚动失败"); } // 方向映射 dx/dy（缺省 600 约一屏）；无 ref 走 window.scrollBy，有 ref 滚元素内部并回传滚动位置
